//! Render the public protection catalogue from the policy consumed by the planner.
use dw4vhp_core::crown::encounters::{importable_models, protected_encounters};
use dw4vhp_core::crown::{RANDOM_DONORS, RANDOM_RULES_VERSION};
fn main() {
    println!("# Randomizer encounter rules\n\n<!-- Generated by npm run docs:rules. Edit the crown policy or this exporter and regenerate. -->\n");
    println!("Current randomizer rules version: **{RANDOM_RULES_VERSION}**.\n");
    println!("## Current rules\n");
    println!("1. **Seeded per stage.** Generator choices are made when the image is built; revisiting a stage does not reroll them. Pharaohmon summon choices roll during play.");
    println!("2. **Resident families plus imports.** Each stage uses eligible native families and up to **{RANDOM_DONORS} imported families**. Unused imports are omitted.");
    println!("3. **Prefer a different family.** Select another compatible family when available; otherwise retain the native enemy.");
    println!("4. **Preserve encounter strength and rarity.** Replacements inherit the original spawn’s HP, attack, defence, wisdom, spirit, speed, status rates/resistances and EXP after selected Crown Mod settings. Fire, ice, thunder and dark resistances use the replacement’s values within ±100 points of the original. Keep the replacement family consistent across difficulties.");
    println!("5. **Preserve rewards and encounter counts.** Keep the original EXP after selected Crown Mod settings. The four-player spawn option controls counts independently.");
    println!("6. **Respect encounter compatibility.** Preserve cannon, fall, jump and other model-specific entrances. Ordinary SQ_NENTR/SQ_SWON activations require the replacement to implement the same named sequence on every difficulty; Pharaohmon uses its native SQ_ENTR for normal activation. Constrain kill-count quests to compatible residents. Randomize practice enemies while preserving lesson objects and generator callbacks. Exclude the developer world and final-boss stages.");
    println!("7. **Make supported scripts follow replacements.** Supported intros, including Minotaurmon, Raremon, Sukamon and Tortamon, retarget their named waits and control/cleanup commands. Mangrove's two pre-boss waves also randomize with matching waits and cleanup, retaining their counts and progression callbacks. Intro replacements are reserved from randomized patrols; wave replacements may share patrol families. ShogunGekomon's boss variants, its scene NPCs and other unsupported boss/script encounters remain native.");
    println!("8. **Random Pharaohmon summons.** Imported Pharaohmon chooses a compatible, already selected stage family on each summon. Consecutive summons choose different families when at least two are available. Dedicated actor slots protect patrols; all Pharaohmon share the native twelve-summon limit. Summons inherit the original Mummymon summon stats and rewards after selected Crown Mod settings, with bounded replacement elemental differences. Exclusive intro/cleanup families, bosses, recursive Pharaohmon summons, and counter-dependent quests are excluded.\n");
    println!("## Importable enemy models\n\nThe following native model families can be imported, in selection order:\n");
    for model in importable_models() {
        println!("- `{model}`");
    }
    println!("\nRegular MR04 (`e_mecha4`) is included; the separate boss model (`e_mecha4bs`) is not an import candidate.\n");
    println!("## Fixed generator protections\n\n| Stage | Pack | Generators | Reason |\n| --- | --- | --- | --- |");
    for rule in protected_encounters() {
        let generators = rule
            .generators
            .iter()
            .map(|s| format!("`{s}`"))
            .collect::<Vec<_>>()
            .join(", ");
        println!(
            "| {} (`{}`) | {} | {} | {} |",
            rule.name, rule.stage, rule.pack_entry, generators, rule.reason
        );
    }
    println!("\n## Additional protections\n\nThese fixed records are not the entire exclusion policy. Model-specific spawn sequences keep their original models; normal entrance/activation overrides require the same named sequence, with the reviewed Pharaohmon SQ_ENTR activation exception. Numenume River’s erase/freeze scripts and Dry Land ruins’ erase scripts follow one exclusive replacement per original family. Family groups retain their native enemies together if local variant slots run out. Stage scripts that address an enemy family by native model name protect that family on the floor, except for explicitly reviewed exceptions. Boss families and native scripted encounters remain protected. Kill-count quests restrict replacements to their compatible resident families.\n\nPractice enemies are eligible, with original encounter stats and practice settings; lesson objects, callbacks and party-size branches remain intact. Practice models never supply donors to other stages. The developer world and final-boss stages are excluded from enemy randomization. Cosmetic crowns are independent of these enemy-replacement rules.\n\nChanging eligibility, ordering or exceptions can change seeded output and requires a randomizer rules-version decision plus corresponding real-disc validation.");
}
